/bin/bash -lc "python3 - <<'PY'
orig={}
for line in open('gwas.ancestry.q1.tsv'):
    f=line.rstrip('\\n').split('\\t')
    orig[int(f[3])]=(f[4],f[5],f[6])
counts={'total':0,'usable':0,'effect_eq_alt':0,'effect_eq_ref':0,'multi_or_mismatch':0,'missing':0}
usable=0
for line in open('extracted_1kg.tsv'):
    parts=line.rstrip('\\n').split('\\t')
    ch,pos,ref,alt=parts[0],int(parts[1]),parts[2],parts[3]
    if ',' in alt:
        # could still be biallelic original; skip for orientation stats
        pass
    if pos not in orig:
        counts['missing']+=1; continue
    eff,oth,p=orig[pos]
    counts['total']+=1
    if ',' not in alt:
        if eff==alt and oth==ref:
            counts['effect_eq_alt']+=1; counts['usable']+=1
        elif eff==ref and oth==alt:
            counts['effect_eq_ref']+=1; counts['usable']+=1
        else:
            counts['multi_or_mismatch']+=1
    else:
        counts['multi_or_mismatch']+=1
print(counts)
PY"

